  };

  push("🔥男生小说🔥", null, 1);
  for (var i = 0; i < b.length; i++) {
    title = b[i].text();
    url = b[i].attr("href");
    size = 0.33;
    title = String(title).replace(/\s/g, "");
    url = String(url).replace(/\/d+\.html$/, "")+"?page={{page}}";
    push(title, url, size);
  };

  push("🔥女生小说🔥", null, 1);
  for (var i = 0; i < c.length; i++) {
    title = c[i].text();
    url = c[i].attr("href");
    size = 0.33;
    title = String(title).replace(/\s/g, "");
    url = String(url).replace(/\/d+\.html$/, "")+"?page={{page}}";
    push(title, url, size);
  };

} else {
  java.toast("🤔列表刷新失败！！！");
}

JSON.stringify(result);

