$.content
<js>
let content = result;
let device, device_type;
try {
    device = java.androidId();
    device_type = '安卓';
} catch (e) {
    try {
        device = java.deviceID();
        device_type = '苹果';
    } catch (e) {
        device = '';
        device_type = '安卓';
    }
