		title: title,
		url: url,
		style: {
				layout_flexGrow: type1,
				layout_flexBasisPercent: type2
			}
	});
push("全部🌊分类",null,1,1)
	arList=["全部","玄幻小说","修真小说","都市小说","历史小说","网游小说","科幻小说","其他小说"]
	arList.map((tag,uri)=>{
		url=`/xclass/${uri}/{{page}}.html`;
		push(tag, url, 1, 0.25);
		});
		push("🌊全本🌊",null,1,1)
	nrList=["全部","玄幻小说","修真小说","都市小说","历史小说","网游小说","科幻小说","其他小说"]
	nrList.map((tag,uri)=>{
		url=`/quanben${uri}_{{page}}.html`;
